#!/usr/bin/env python3
"""Native window/worker event initialization, dispatch and microtask regressions.

These bounded platform checks supplement unchanged upstream WPT fixtures.
They exercise actual same-origin iframe and dedicated-worker runtimes.
"""
import argparse
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
import json
import os
from pathlib import Path
import subprocess
import sys
import tempfile
import threading

